function installRadius(camera: GeospatialCamera, state: ModeState): boolean {
  const cam = camera as any;
  const desc = findDescriptor(cam, "radius");
  const originalGet = desc?.get as (() => number) | undefined;
  const originalSet = desc?.set as ((value: number) => void) | undefined;
  let backing = typeof cam.radius === "number" ? cam.radius : 0;
  let applyingInternal = false;
  try {
    Object.defineProperty(cam, "radius", {
      configurable: true,
      enumerable: desc?.enumerable ?? false,
      get(): number {
        if (originalGet) return originalGet.call(cam);
        return backing;
      },
      set(value: number): void {
        if (applyingInternal) {
          if (!originalGet) backing = value;
          return;
        }
        const current = originalGet ? originalGet.call(cam) : backing;
        const clamped = clampRadius(value, state.limits, current);
        applyingInternal = true;
        try {
          if (originalSet) {
            originalSet.call(cam, clamped);
          } else if (typeof cam._setOrientation === "function") {
            backing = clamped;
            cam._setOrientation(cam.yaw, cam.pitch, clamped, cam.center);
          } else {
            backing = clamped;
          }
        } finally {
          applyingInternal = false;
        }
      }
    });
    return true;
  } catch {
    return false;
  }
}
```
