      enumerable: desc?.enumerable ?? false,
      get(): GeospatialLimits { return state.limits; },
      set(value: GeospatialLimits): void {
        if (applyingLimits) { state.limits = value; return; }
        applyingLimits = true;
        try {
          state.limits = value;
          if (originalSet) originalSet.call(cam, value);
        } finally { applyingLimits = false; }
      }
    });
    return true;
  } catch { return false; }
}
